{"findings":[{"tipo":"GC","causa_raiz":"Alocação excessiva e contínua de memória na Heap gerenciada dentro do método Update(), gerada pela concatenação iterativa de strings ('s += i.ToString()'), criação frequente de arrays ('new object[10000]') e busca global de componentes ('FindObjectsOfType<GameObject>()'). Essa carga gerou cerca de 5,15 MB de alocação por frame, disparando coletas de lixo síncronas (GC.Collect) que paralisaram a CPU por 22,75 ms no frame 170.","codigo_refatorado":"using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _stringBuilder;
        private MaterialPropertyBlock _propBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _stringBuilder = new StringBuilder(gcConcatIterations * 4);
            _propBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                var col = quad.GetComponent<Collider>();
                if (col != null) Destroy(col);
                quad.name = string.Concat("Overdraw_", i);
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _stringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _stringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int childCount = transform.childCount;
                    GC.KeepAlive(childCount);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    Color randomColor = new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value);
                    renderer.GetPropertyBlock(_propBlock);
                    _propBlock.SetColor(ColorPropertyId, randomColor);
                    renderer.SetPropertyBlock(_propBlock);
                }
            }
        }
    }
}","explicacao_didatica":"Em C#, textos (strings) e novos vetores (arrays) criados dentro do Update() não são reaproveitados automaticamente. Toda vez que você usa 's += i.ToString()', o computador cria um texto novinho na memória e abandona o anterior no lixo. Quando esse lixo acumula (neste caso, mais de 5 MB a cada frame), o Garbage Collector (o 'lixeiro' da memória) precisa paralisar o jogo para recolher toda essa sujeira, causando travadas bruscas (stuttering). Para evitar isso, reutilizamos buffers como o StringBuilder, evitamos buscas pesadas a cada quadro e usamos MaterialPropertyBlock para trocar cores sem duplicar materiais."}],"dicas_level_design":null}

